import { GoogleGenAI } from "@google/genai";

const SYSTEM_INSTRUCTION = `
You are the AI Assistant for Alex, a world-class Senior React Developer. 
Your goal is to answer questions about Alex's professional experience, services, and personality.

Key Facts about Alex:
- 8+ years experience in Frontend Engineering.
- Specializes in React, TypeScript, and AI integrations.
- Services provided: Modern Web Apps, UI/UX Design, AI Solutions, Performance Optimization.
- Tech Stack: React, Next.js, Tailwind, Node.js, Gemini API, D3.js.
- Personality: Professional, creative, and detail-oriented.
- Location: London / Remote.

Answer concisely and professionally. If someone asks for a quote, suggest they use the contact form.
Always be polite and helpful.
`;

export async function chatWithAI(message: string, history: { role: 'user' | 'model', parts: { text: string }[] }[]) {
  const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });

  try {
    const response = await ai.models.generateContent({
      model: 'gemini-3-flash-preview',
      contents: message,
      config: {
        systemInstruction: SYSTEM_INSTRUCTION,
        temperature: 0.7,
      },
    });

    return response.text;
  } catch (error) {
    console.error("Gemini AI Error:", error);
    return "I'm sorry, I'm having trouble connecting right now. Please try again or use the contact form below.";
  }
}

